begin;

-- Keep already-issued order references stable; every newly submitted order
-- generated by submit_multi_product_order receives the next short reference.
create sequence if not exists public.order_number_short_seq
  as bigint
  minvalue 110021
  start with 110021
  increment by 1
  no cycle;

do $$
declare
  v_max_existing bigint;
  v_sequence_last_value bigint;
begin
  select coalesce(max(substring(o.order_number from '^D([0-9]+)$')::bigint), 110021)
    into v_max_existing
  from public.orders o;

  select last_value into v_sequence_last_value
  from public.order_number_short_seq;

  perform setval(
    'public.order_number_short_seq'::regclass,
    greatest(v_max_existing, v_sequence_last_value, 110021),
    true
  );
end;
$$;

create or replace function public.assign_short_order_number()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
begin
  -- The existing authoritative order RPC supplies this legacy-shaped
  -- temporary value. Replace it at the database boundary with the short ID.
  if new.order_number like 'ORD-%' then
    new.order_number := 'D' || nextval('public.order_number_short_seq'::regclass)::text;
  end if;
  return new;
end;
$$;

drop trigger if exists assign_short_order_number on public.orders;
create trigger assign_short_order_number
before insert on public.orders
for each row
execute function public.assign_short_order_number();

revoke all on function public.assign_short_order_number() from public;
revoke all on function public.assign_short_order_number() from anon;
revoke all on function public.assign_short_order_number() from authenticated;
revoke all on sequence public.order_number_short_seq from public;
revoke all on sequence public.order_number_short_seq from anon;
revoke all on sequence public.order_number_short_seq from authenticated;

comment on sequence public.order_number_short_seq is
  'Generates compact, monotonically increasing order references for new orders.';

commit;
